#include "acc3d.h"

#ifdef ACC3D_ENABLE_STDIO
#include <stdio.h>
#include <string.h>

int acc3d_load_file(const char *path, char *buffer, size_t buffer_cap, size_t *out_size)
{
    FILE *f;
    size_t n;
    if (path == (const char *)0 || buffer == (char *)0 || buffer_cap == 0) return ACC3D_ERR_ARG;
    f = fopen(path, "rb");
    if (f == (FILE *)0) return ACC3D_ERR_PARSE;
    n = fread(buffer, 1, buffer_cap, f);
    if (ferror(f)) {
        fclose(f);
        return ACC3D_ERR_PARSE;
    }
    fclose(f);
    if (out_size != (size_t *)0) *out_size = n;
    return ACC3D_OK;
}

static void write_fix(FILE *f, acc3d_fix v)
{
    char b[48];
    acc3d_fixed_to_ascii(v, b, sizeof(b), 6);
    fputs(b, f);
}

int acc3d_write_obj_file(const char *path, const struct acc3d_model *model)
{
    FILE *f;
    long i;
    if (path == (const char *)0 || model == (const struct acc3d_model *)0) return ACC3D_ERR_ARG;
    f = fopen(path, "wb");
    if (f == (FILE *)0) return ACC3D_ERR_PARSE;
    fputs("# generated by acc3d_codec_c89\n", f);
    for (i = 0; i < model->vertex_count; ++i) {
        fputs("v ", f);
        write_fix(f, model->vertices[i].x); fputc(' ', f);
        write_fix(f, model->vertices[i].y); fputc(' ', f);
        write_fix(f, model->vertices[i].z); fputc('\n', f);
    }
    for (i = 0; i < model->ref_count; ++i) {
        fputs("vt ", f);
        write_fix(f, model->refs[i].uv.u); fputc(' ', f);
        write_fix(f, model->refs[i].uv.v); fputc('\n', f);
    }
    for (i = 0; i < model->triangle_count; ++i) {
        const struct acc3d_triangle *t;
        t = &model->triangles[i];
        fprintf(f, "f %ld/%ld %ld/%ld %ld/%ld\n",
            t->v[0] + 1L, t->ref_index[0] + 1L,
            t->v[1] + 1L, t->ref_index[1] + 1L,
            t->v[2] + 1L, t->ref_index[2] + 1L);
    }
    fclose(f);
    return ACC3D_OK;
}

int acc3d_write_summary_file(const char *path, const struct acc3d_model *model)
{
    FILE *f;
    long i;
    if (path == (const char *)0 || model == (const struct acc3d_model *)0) return ACC3D_ERR_ARG;
    f = fopen(path, "wb");
    if (f == (FILE *)0) return ACC3D_ERR_PARSE;
    fprintf(f, "ACC3D summary\n");
    fprintf(f, "version_hex=%ld suffix=%ld strip_suffix=%ld acc_like=%ld diag_bits=0x%lx\n",
        model->version_hex, model->header_has_suffix, model->header_has_strip_suffix,
        model->is_acc_like, model->diag_bits);
    fprintf(f, "materials=%ld objects=%ld vertices=%ld surfaces=%ld refs=%ld triangles=%ld\n",
        model->material_count, model->object_count, model->vertex_count,
        model->surface_count, model->ref_count, model->triangle_count);
    for (i = 0; i < model->object_count; ++i) {
        fprintf(f, "object[%ld] parent=%ld type=%s name=%s verts=%ld surfs=%ld kids=%ld texture=%s\n",
            i, model->objects[i].parent, model->objects[i].type, model->objects[i].name,
            model->objects[i].vertex_count, model->objects[i].surface_count,
            model->objects[i].kids_declared, model->objects[i].texture);
    }
    fclose(f);
    return ACC3D_OK;
}
#endif
